function rotate(v,inverse=false){const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch);if(inverse){const y=v[1]*cp+v[2]*sp,z=-v[1]*sp+v[2]*cp;return[v[0]*cy-z*sy,y,v[0]*sy+z*cy]}const x=v[0]*cy+v[2]*sy,z=-v[0]*sy+v[2]*cy;return[x,v[1]*cp-z*sp,v[1]*sp+z*cp]}
const radius=()=>202*zoom;
function project(v){const p=rotate(v);return[240+p[0]*radius(),240-p[1]*radius(),p[2]]}

const landmarkPins=new Map();
function renderLandmarks(routes,focus){
 const slot=$('[data-earth-landmarks]'),points=new Map();
 slot.style.setProperty('--earth-pin-scale',String(zoom));
 // One pin per resolved city; a shared endpoint belongs to the focused leg.
 for(const route of routes)for(const end of ['from','to']){const city=location(route,end),key=String(city[0]);if(!points.has(key)||route.id===focus)points.set(key,{city,route,end})}
 for(const [key,pin] of landmarkPins)if(!points.has(key)){pin.remove();landmarkPins.delete(key)}
 for(const [key,{city,route,end}] of points){
  let pin=landmarkPins.get(key);
  if(!pin){pin=document.createElement('button');pin.type='button';pin.className='earth-map-pin';slot.append(pin);landmarkPins.set(key,pin)}
  if(!pin.firstChild)pin.innerHTML='<svg viewBox="0 0 32 44" aria-hidden="true"><path class="earth-pin-shell" d="M16 42C13 37 2 25 2 16A14 14 0 0 1 30 16C30 25 19 37 16 42Z"/><circle class="earth-pin-hole" cx="16" cy="16" r="5"/></svg>';
  pin.setAttribute('aria-label',`${route[end]}，城市定位，查看旅行详情`);pin.dataset.city=route[end];pin.dataset.routeId=route.id;pin.onclick=()=>detail(route);
  const point=project(C().vec(city[4],city[5]));pin.hidden=point[2]<=.08||point[0]<18||point[0]>462||point[1]<40||point[1]>480;
  pin.style.left=point[0]/480*100+'%';pin.style.top=point[1]/480*100+'%';pin.classList.toggle('is-active',route.id===focus);
 }
}

